import { useEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { Link, useLocation, useNavigate, useParams } from 'react-router-dom';
import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUp, BarChart3, Bell, Check, CheckCircle2, ChevronRight, CircleHelp, Clock3, Copy, Database, FileText, Fuel, Grid2X2, LayoutDashboard, LineChart, Map, Maximize2, Mic, MoreHorizontal, Package, Palette, Paperclip, Pencil, Play, Plus, Search, Settings2, Share2, ShieldCheck, SlidersHorizontal, Sparkles, Star, Sun, Target, ThumbsUp, TrendingUp, Truck, Users, WandSparkles, X } from 'lucide-react';
import type { EChartsCoreOption } from 'echarts/core';
import { asset, downloadText, uid, useDemo, type Dashboard } from '../demo';
import { Badge, Modal, toast, useDocumentTitle } from '../ui';
import { Chart } from './Chart';
import './dashboards.css';

const DEFAULT_REQUEST='Собери дашборд по вывозу отходов за 7 дней. Хочу видеть рейсы, массу, перевозчиков, объекты образования отходов, объекты приёма и эффективность.';
const SOURCE_NAMES=['Мос.Дата','Цифровой двойник Москвы','Внутренние системы','Файлы пользователя'];
const PRESETS=[{name:'Тёмный оперативный',image:'e3acb.png',theme:'dark'}, {name:'Руководительский светлый',image:'cdcb6.png',theme:'light'}, {name:'Территориальный с картой',image:'58b1a.png',theme:'light'}, {name:'Глубокая аналитика',image:'219ae.png',theme:'light'}];
const QUICK=[{title:'Оперативная сводка по топливу',desc:'Текущая ситуация и тренды',icon:Fuel},{title:'Контроль KPI',desc:'План/факт и отклонения',icon:Truck},{title:'Аналитика маршрутов',desc:'Эффективность и оптимизация',icon:Activity},{title:'Управление запасами',desc:'Остатки и прогноз поставок',icon:Package},{title:'Журнал инцидентов',desc:'Отчёты и меры реагирования',icon:Clock3},{title:'Техобслуживание',desc:'Графики ТО и состояние техники',icon:Settings2}];
type Draft={request:string;name:string;step:number;audience:string;preset:number;density:string;theme:string;composition:string;focus:string;character:string;sources:string[];fixed:boolean;file:string};
const NEW_DRAFT:Draft={request:DEFAULT_REQUEST,name:'Мониторинг вывоза отходов',step:0,audience:'Руководитель',preset:0,density:'Компактно',theme:'dark',composition:'Аналитическая',focus:'KPI',character:'Технологичный',sources:['Цифровой двойник Москвы','Внутренние системы'],fixed:false,file:''};
type ChartKind='scatter'|'line'|'bar'|'heatmap';
type WidgetConfig={type:ChartKind;color:string;legend:boolean;grid:boolean;size:number};
type Comment={id:string;name:string;initials:string;avatar?:string;text:string;time:string;likes:number;liked?:boolean};
type EditorSettings={period:string;carrier:string;origin:string;waste:string;theme:string;tab:string;selected:string;configs:Record<string,WidgetConfig>;comments:Comment[];access:string;refresh:string;notify:boolean;projectId?:string};
type SavedState={draft?:Draft;editors?:Record<string,EditorSettings>};
function readSaved():SavedState {try{return JSON.parse(localStorage.getItem('lab-cd-wizard')||'{}') as SavedState;}catch{return {};}}
function writeSaved(patch:Partial<SavedState>){try{localStorage.setItem('lab-cd-wizard',JSON.stringify({...readSaved(),...patch}));}catch{/* Demo still works without persistence. */}}
const INITIAL_COMMENTS:Comment[]=[
{id:'c1',name:'Анастасия К.',initials:'АК',avatar:'f5a5a.png',text:'Сделать график компактнее, чтобы не занимал столько места.',time:'10:15',likes:2},
{id:'c2',name:'Мария С.',initials:'МС',avatar:'4db17.png',text:'Вынести топ перевозчиков выше — это ключевой блок для руководства.',time:'11:02',likes:3},
{id:'c3',name:'Дмитрий В.',initials:'ДВ',avatar:'d8d89.png',text:'Поддерживаю, пусть будет в первой строке.',time:'11:05',likes:1},
{id:'c4',name:'Иван П.',initials:'ИП',avatar:'370c2.png',text:'Почему сегодня рейсов на одно ТС резко ниже? Нужно разобраться с причиной.',time:'11:10',likes:4},
{id:'c5',name:'Алексей Р.',initials:'АР',avatar:'b3939.png',text:'Хороший рост среднего в день продолжается, +36% к предыдущему периоду — отличная динамика.',time:'11:18',likes:5},
{id:'c6',name:'Ольга Н.',initials:'ОН',avatar:'d729c.png',text:'Да, но снижение доли объектов приёма настораживает — нужен анализ.',time:'11:22',likes:2}];
const WIDGETS=[{id:'carriers',title:'Топ-5 перевозчиков',sub:'По объёму вывезенных отходов',color:'#4097ff',type:'bar' as ChartKind},{id:'origins',title:'Топ объектов образования',sub:'Рейтинг по массе отходов',color:'#9bdb53',type:'bar' as ChartKind},{id:'destinations',title:'Топ объектов приёма',sub:'Распределение нагрузки',color:'#a177ff',type:'bar' as ChartKind},{id:'heatmap',title:'Интенсивность рейсов',sub:'По дням недели и часам',color:'#3598ff',type:'heatmap' as ChartKind},{id:'efficiency',title:'Эффективность перевозчиков',sub:'Рейсы и вывезенная масса',color:'#477bff',type:'scatter' as ChartKind}];
function defaultSettings(theme='dark'):EditorSettings{return {period:'7 дней',carrier:'Все перевозчики',origin:'Все объекты образования',waste:'Все виды отходов',theme,tab:'Аналитика',selected:'efficiency',access:'команда',refresh:'ежедневно',notify:false,configs:Object.fromEntries(WIDGETS.map(w=>[w.id,{type:w.type,color:w.color,legend:false,grid:true,size:7}])),comments:INITIAL_COMMENTS};}
function num(n:number,digits=0){return new Intl.NumberFormat('ru-RU',{maximumFractionDigits:digits,minimumFractionDigits:digits}).format(n);}
function IconBox({children,tone='pink'}:{children:ReactNode;tone?:string}){return <span className={'dash-icon dash-icon-'+tone}>{children}</span>;}
function Choice({value,onChange,options}:{value:string;onChange:(v:string)=>void;options:string[]}){return <div className="dash-choices">{options.map(v=><button type="button" key={v} className={'dash-choice '+(value===v?'is-active':'')} aria-pressed={value===v} onClick={()=>onChange(v)}>{v}</button>)}</div>;}
function Prompt({onSubmit,placeholder='Напишите ответ или уточнение...',large=false,defaultValue='',buttonLabel='Отправить запрос'}:{onSubmit:(v:string)=>void;placeholder?:string;large?:boolean;defaultValue?:string;buttonLabel?:string}){
 const [text,setText]=useState(defaultValue);const [attachment,setAttachment]=useState('');const file=useRef<HTMLInputElement>(null);
 return <form className={'dash-prompt '+(large?'dash-prompt-large':'')} onSubmit={e=>{e.preventDefault();if(text.trim()){onSubmit(text.trim());setText('');}}}>
  <textarea aria-label={placeholder} value={text} onChange={e=>setText(e.target.value)} placeholder={placeholder} rows={large?2:1} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();if(text.trim()){onSubmit(text.trim());setText('');}}}} />
  {attachment&&<span className="dash-attachment"><FileText size={13}/>{attachment}<button type="button" aria-label="Убрать файл" onClick={()=>setAttachment('')}><X size={12}/></button></span>}
  <div className="dash-prompt-actions"><div><input type="file" ref={file} hidden onChange={e=>{if(e.target.files?.[0]){setAttachment(e.target.files[0].name);toast('Файл добавлен к демозапросу');}}}/><button type="button" className="icon-btn" title="Прикрепить файл" aria-label="Прикрепить файл" onClick={()=>file.current?.click()}><Paperclip size={17}/></button><button type="button" className="icon-btn" title="Пример голосового запроса" aria-label="Пример голосового запроса" onClick={()=>{setText(DEFAULT_REQUEST);toast('Добавлен пример голосового запроса');}}><Mic size={16}/></button></div><button className="dash-send" type="submit" aria-label={buttonLabel} disabled={!text.trim()}><ArrowUp size={18}/></button></div>
 </form>;
}

export function DashboardsPage(){const location=useLocation();const {id}=useParams();useDocumentTitle('Дашборды');if(location.pathname.endsWith('/new'))return <DashboardWizard/>;if(id)return <DashboardEditor key={id} id={id} published={!location.pathname.endsWith('/edit')}/>;return <DashboardGallery/>;}

function DashboardGallery(){
 const dashboards=useDemo(s=>s.dashboards);const navigate=useNavigate();const [all,setAll]=useState(false);const [filter,setFilter]=useState('');
 function start(request:string){const name=/топлив/i.test(request)?'Оперативная сводка по топливу':/KPI/i.test(request)?'Контроль KPI':/маршрут/i.test(request)?'Аналитика маршрутов':'Мониторинг вывоза отходов';writeSaved({draft:{...NEW_DRAFT,request,name}});navigate('/dashboards/new');}
 const shown=dashboards.filter(d=>d.name.toLowerCase().includes(filter.toLowerCase()));
 return <div className="dash-page dash-gallery"><header className="dash-gallery-heading"><h1>Какой дашборд вы хотите создать?</h1><p>Опишите бизнес-задачу, а ИИ предложит структуру, данные и первый драфт</p></header>
 <Prompt large onSubmit={start} placeholder="Например: сделай дашборд по вывозу отходов за последние 7 дней — с массой, рейсами и объектами образования отходов" buttonLabel="Создать дашборд"/>
 <div className="dash-quick-grid">{QUICK.map(({title,desc,icon:Icon})=><button key={title} className="dash-quick" onClick={()=>start('Создай дашборд «'+title+'» за последние 7 дней. Покажи ключевые показатели, динамику и эффективность.')}><IconBox><Icon size={19}/></IconBox><strong>{title}</strong><span>{desc}</span><ArrowRight className="dash-quick-arrow" size={15}/></button>)}</div>
 <section className="panel dash-recent"><div className="dash-section-heading"><h3>{all?'Все дашборды':'Вы недавно работали'}</h3><button className="dash-text-button" onClick={()=>setAll(!all)}>{all?'Недавние':'Все дашборды'} <ArrowRight size={13}/></button></div>{all&&<div className="dash-search"><Search size={16}/><input aria-label="Поиск дашбордов" placeholder="Поиск дашбордов..." value={filter} onChange={e=>setFilter(e.target.value)}/><button className="btn btn-primary" onClick={()=>start(DEFAULT_REQUEST)}><Plus size={15}/>Новый дашборд</button></div>}
 <div className="dash-dashboard-cards">{shown.map((d,i)=><Link className="dash-dashboard-card" to={'/dashboards/'+d.id+(d.published?'':'/edit')} key={d.id}><img src={asset(PRESETS[i%4].image)} alt={'Предпросмотр: '+d.name}/><strong>{d.name==='Мониторинг вывоза отходов'?'Вывоз отходов':d.name}</strong><p>{d.description}</p><span>Обновлён {d.updated.toLowerCase()}</span></Link>)}</div>{!shown.length&&<div className="dash-empty">По этому запросу дашбордов нет</div>}</section>
 </div>;
}

function DashboardWizard(){
 const navigate=useNavigate();const location=useLocation();const saveDashboard=useDemo(s=>s.saveDashboard);const [draft,setDraft]=useState<Draft>(()=>{const stored={...NEW_DRAFT,...readSaved().draft};const query=new URLSearchParams(location.search);const request=query.get('prompt')||query.get('request');return request?{...stored,request,step:0,name:/топлив/i.test(request)?'Оперативная сводка по топливу':/KPI/i.test(request)?'Контроль KPI':/маршрут/i.test(request)?'Аналитика маршрутов':'Мониторинг вывоза отходов'}:stored;});const [percent,setPercent]=useState(0);const [sourceQuery,setSourceQuery]=useState('Найди рейсы, массу отходов, перевозчиков, объекты образования и объекты приёма за последние 7 дней');const [sourceFound,setSourceFound]=useState(false);const [aiNote,setAiNote]=useState('');const file=useRef<HTMLInputElement>(null);
 function update(p:Partial<Draft>){setDraft(d=>({...d,...p}));}
 useEffect(()=>{writeSaved({draft});},[draft]);
 useEffect(()=>{if(draft.step!==4)return;setPercent(0);const started=Date.now();let done=false;const timer=window.setInterval(()=>{const next=Math.min(100,Math.round((Date.now()-started)/65));setPercent(next);if(next>=100&&!done){done=true;window.clearInterval(timer);const id='dashboard-'+uid().slice(0,8);saveDashboard({id,name:draft.name,description:draft.request,theme:draft.theme,audience:draft.audience,period:'7 дней',sources:draft.sources,published:false,updated:'Только что'});writeSaved({draft:{...draft,step:0}});navigate('/dashboards/'+id+'/edit');}},140);return ()=>window.clearInterval(timer);},[draft.step,navigate,saveDashboard,draft.name,draft.request,draft.theme,draft.audience,draft.sources]);
 const next=()=>update({step:draft.step+1});const back=()=>draft.step>0?update({step:draft.step-1}):navigate('/dashboards');
 const heading=['Для кого готовим дашборд?','Уточните стиль визуализации дашборда','Подключите источники данных','ИИ подготовил план данных','ИИ собирает первый драфт'][draft.step];
 const sub=['Выберите аудиторию, чтобы подобрать нужные показатели','ИИ проанализировал ваш запрос. Выберите визуальный стиль и ответьте на несколько вопросов для точного результата','Подтвердите, откуда ИИ возьмёт показатели для дашборда','Проверьте источники, метрики и логику расчётов перед генерацией','Готовим структуру, показатели и визуализации на демонстрационных данных'][draft.step];
 return <div className={'dash-page dash-wizard '+(draft.step===0?'dash-audience-page':'')}>
 {draft.step===0?<><div className="dash-audience-work"><div className="dash-editor-heading"><strong>{draft.name}</strong><button className="dash-text-button" onClick={()=>toast('Черновик сохранён в этом браузере')}><ShieldCheck size={14}/>Черновик сохранён</button></div><div className="dash-user-bubble">{draft.request}<span>12:34 <Check size={13}/></span></div><div className="dash-ai-bubble"><div className="dash-ai-intro"><IconBox><Sparkles size={20}/></IconBox><p>Понял. Собираем оперативный дашборд. Сначала уточним несколько параметров.</p></div><h3>Для кого готовим дашборд?</h3><Choice value={draft.audience} onChange={audience=>update({audience})} options={['Руководитель','Аналитик','Диспетчер']}/><button className="btn btn-primary dash-audience-next" onClick={next}>Продолжить <ArrowRight size={15}/></button></div><div className="dash-audience-prompt"><Prompt onSubmit={v=>{setAiNote('Учту ваше уточнение: «'+v+'»');}}/>{aiNote&&<div className="dash-inline-note">{aiNote}</div>}</div></div><aside className="dash-brief"><h3>Бриф дашборда</h3>{[['Тема',draft.name],['Период','7 дней'],['Территория','Москва'],['Аудитория',draft.audience],['Стиль','не выбран'],['Источники','не выбраны']].map(([label,value],i)=><div className="dash-brief-item" key={label}><IconBox tone={i<3?'green':'pink'}>{i<3?<Check size={15}/>:i===3?<Users size={16}/>:i===4?<Palette size={16}/>:<Database size={16}/>}</IconBox><div><span>{label}</span><strong>{value}</strong></div></div>)}<small>Параметры будут уточняться по мере диалога <CircleHelp size={13}/></small></aside></>:<>
 <header className="dash-step-heading"><h1>{heading}</h1><p>{sub}</p></header>
 {draft.step===1&&<div className="dash-style-layout"><section className="panel dash-style-controls"><h3>Параметры подачи</h3>{[{label:'Аудитория',icon:Users,key:'audience',options:['Руководитель','Аналитик','Диспетчер']},{label:'Плотность',icon:SlidersHorizontal,key:'density',options:['Компактно','Сбалансировано','Детально']},{label:'Цветовая тема',icon:Palette,key:'theme',options:['Светлая','Тёмная','Авто']},{label:'Тип композиции',icon:LayoutDashboard,key:'composition',options:['Модульная сетка','Аналитическая','Оперативная']},{label:'Основной акцент',icon:Target,key:'focus',options:['KPI','Графики','Карта','Рейтинги']},{label:'Характер UI',icon:Sparkles,key:'character',options:['Строгий','Премиальный','Технологичный']}].map(({label,icon:Icon,key,options})=><div className="dash-control-group" key={key}><label><Icon size={16}/>{label}</label><Choice value={key==='theme'?(draft.theme==='dark'?'Тёмная':draft.theme==='light'?'Светлая':'Авто'):String(draft[key as keyof Draft])} options={options} onChange={v=>update(key==='theme'?{theme:v==='Тёмная'?'dark':v==='Светлая'?'light':'auto'}:{[key]:v})}/></div>)}</section><div className="dash-style-right"><section className="panel dash-presets"><h3>ИИ-пресеты</h3><div className="dash-presets-grid">{PRESETS.map((preset,i)=><button className={'dash-preset '+(draft.preset===i?'is-active':'')} key={preset.name} onClick={()=>update({preset:i,theme:preset.theme})}><div><strong><span>{i+1}</span>{preset.name}</strong>{i===0?<span className="dash-recommended">РЕКОМЕНДУЕМ</span>:draft.preset===i?<CheckCircle2 size={16}/>:null}</div><img src={asset(preset.image)} alt={preset.name}/></button>)}</div></section><section className="panel dash-style-ai"><h3><Sparkles size={16}/> ИИ-ассистент</h3><Prompt onSubmit={v=>{setAiNote('Для задачи «'+v+'» рекомендую '+PRESETS[draft.preset].name.toLowerCase()+': ключевые показатели будут видны сразу.');}} placeholder="Задайте вопрос по дашборду..."/>{aiNote&&<p className="dash-inline-note">{aiNote}</p>}</section></div></div>}
 {draft.step===2&&<div className="dash-sources-layout"><div><div className="dash-source-grid">{SOURCE_NAMES.map((source,i)=>{const connected=draft.sources.includes(source);return <section className={'panel dash-source-card '+(connected?'is-connected':'')+' dash-source-'+i} key={source}>{i===1&&<span className="dash-key-source"><Star size={11}/>КЛЮЧЕВОЙ ИСТОЧНИК</span>}<div className="dash-source-heading"><IconBox tone={['pink','blue','violet','green'][i]}>{i===0?<BarChart3 size={24}/>:i===1?<Map size={24}/>:i===2?<Database size={24}/>:<FileText size={24}/>}</IconBox><div><h3>{source}</h3><p>{['городские показатели и открытые наборы','слои, объекты, геометрия','корпоративные БД и API','Excel, CSV, PDF, GeoJSON'][i]}</p></div></div><div className="dash-source-status"><Badge tone={connected?'green':'gray'}>{connected?<><CheckCircle2 size={13}/>Подключено</>:'● Доступно'}</Badge><button className={'btn '+(connected?'btn-secondary':'')} onClick={()=>{if(i===3&&!connected){file.current?.click();}else{update({sources:connected?draft.sources.filter(x=>x!==source):[...draft.sources,source]});}}}>{connected?'Отключить':'Подключить'}</button></div><p className="dash-security"><ShieldCheck size={15}/>{i===1?'Демослой содержит географию, объекты и территориальный контекст.':'В прототипе используются демонстрационные данные'}</p>{i===3&&draft.file&&<span className="dash-file-label"><Paperclip size={12}/>{draft.file}</span>}</section>})}</div><input ref={file} type="file" accept=".csv,.xlsx,.xls,.json,.geojson,.pdf" hidden onChange={e=>{const name=e.target.files?.[0]?.name;if(name){update({file:name,sources:[...new Set([...draft.sources,'Файлы пользователя'])]});toast('Файл '+name+' добавлен как демоисточник');}}}/><section className="dash-ai-search"><div><IconBox><Sparkles size={23}/></IconBox><div><h3>ИИ поможет найти нужные данные</h3><p>Опишите, что ищете — ИИ подберёт подходящие источники и поля</p></div></div><form onSubmit={e=>{e.preventDefault();if(sourceQuery.trim()){setSourceFound(true);update({sources:[...new Set([...draft.sources,'Мос.Дата','Внутренние системы'])]});toast('Найдено 6 демонстрационных источников');}}}><Search size={15}/><input aria-label="Поиск источников" value={sourceQuery} onChange={e=>setSourceQuery(e.target.value)}/><button className="dash-send" type="submit" aria-label="Найти источники"><ArrowUp size={17}/></button></form></section></div><aside className="panel dash-found-sources"><h3><IconBox><Activity size={15}/></IconBox>Найденные источники</h3>{['Реестры рейсов','Масса и взвешивание','Объекты образования','Объекты приёма','Справочник перевозчиков','География по округам'].map((name,i)=><div key={name}><CheckCircle2 size={19}/><span><strong>{name}</strong><small>{i===5?'ЦД':i===2||i===3?'реестр объектов':'внутренняя система'}</small></span></div>)}<p className="dash-verified"><ShieldCheck size={16}/>{sourceFound?'Подобраны источники по вашему запросу. Связи и географический контекст учтены.':'Источники доступны для демонстрации. ИИ учтёт связи между данными и географический контекст.'}</p></aside></div>}
 {draft.step===3&&<div className="dash-plan"><div className="dash-plan-main"><section className="panel dash-plan-sources"><h3><span className="dash-number">1</span>Источники</h3><div className="dash-plan-table"><div><span>Показатель</span><span>Источник</span><span>Период</span><span>Статус</span></div>{['Количество рейсов','Масса отходов','Перевозчики','Объекты образования','Объекты приёма'].map((name,i)=><div key={name}><strong>{name}</strong><span>{i<3?'внутренняя система':'реестр объектов'}</span><span>{i<3?'7 дней':'актуально'}</span><span className="dash-found"><CheckCircle2 size={14}/>найдено</span></div>)}</div></section><section className="panel dash-calculated"><h3><span className="dash-number">2</span>Расчётные показатели</h3><div>{[{name:'Доля завершённых рейсов',desc:'% завершённых от общего числа',icon:Activity,tone:'green'},{name:'Средняя масса рейса',desc:'Масса отходов на один рейс',icon:TrendingUp,tone:'blue'},{name:'Задействованность ресурсов',desc:'Использование ТС и исполнителей',icon:Users,tone:'orange'},{name:'Топ-объекты приёма',desc:'Объёмы по объекту и количеству рейсов',icon:Package,tone:'green'},{name:'Топ-перевозчики',desc:'Перевозчики по объёму и эффективности',icon:Truck,tone:'violet'}].map(({name,desc,icon:Icon,tone})=><article key={name}><IconBox tone={tone}><Icon size={20}/></IconBox><div><strong>{name}</strong><p>{desc}</p></div></article>)}</div></section></div><aside className="panel dash-plan-notes"><h3>{draft.fixed?<span className="dash-found"><CheckCircle2 size={16}/>Замечания исправлены</span>:'Найдены замечания'}</h3>{draft.fixed?<p className="dash-fixed">Названия районов приведены к единому формату. Пропуски отмечены в наборе данных. Можно создавать дашборд.</p>:<>{['В двух наборах различаются названия районов','Для 3 районов не хватает исторических данных','Можно автоматически привести показатели к единому формату'].map((text,i)=><p key={text}><IconBox tone={i===2?'blue':'orange'}>{i===2?<CircleHelp size={16}/>:<CircleHelp size={16}/>}</IconBox>{text}</p>)}</>}<button className="btn btn-secondary" onClick={()=>{update({fixed:!draft.fixed});toast(draft.fixed?'Показаны исходные замечания':'Форматы приведены к единому виду');}}><WandSparkles size={15}/>{draft.fixed?'Показать исходный план':'Исправить автоматически'}</button></aside><section className="panel dash-plan-structure"><h3><span className="dash-number">3</span>Структура дашборда</h3><div>{[{name:'KPI',icon:BarChart3,desc:'Ключевые показатели по отходам и перевозкам'},{name:'Структура отходов',icon:Activity,desc:'Состав отходов по видам и классам опасности'},{name:'Доля завершённых рейсов',icon:CheckCircle2,desc:'Мониторинг выполнения и отмен рейсов'},{name:'Ресурсы',icon:Users,desc:'Загрузка транспорта и объектов во времени'},{name:'Топы',icon:Star,desc:'Рейтинги объектов и перевозчиков'},{name:'Тепловая карта',icon:Map,desc:'География и интенсивность перевозок'},{name:'Эффективность перевозчиков',icon:TrendingUp,desc:'Анализ результативности по ключевым метрикам'}].map(({name,icon:Icon,desc},i)=><article key={name}><div><Icon size={19}/><span>0{i+1}</span></div><strong>{name}</strong><p>{desc}</p></article>)}</div></section></div>}
 {draft.step===4&&<div className="dash-generation-layout"><div><section className="panel dash-generation"><div className="dash-progress-ring" style={{'--dash-progress':percent+'%'} as CSSProperties}><div><Sparkles size={34}/><strong>{percent}%</strong><b>{['Подготовка данных','Поиск источников','Сборка структуры','Проверка результата','Формирование драфта'][Math.min(4,Math.floor(percent/21))]}</b><span>в процессе</span></div></div><div className="dash-generation-steps">{['Формирование ТЗ и визуального стиля','Поиск источников и подготовка выборки','Сборка структуры','Проверка результата','Работа с сервисом прав','Формирование драфта'].map((label,i)=><div className={percent>i*16.7?'is-done':''} key={label}><span>{percent>(i+1)*16.7?<Check size={14}/>:String(i+1).padStart(2,'0')}</span><p>{label}</p></div>)}</div></section><section className="panel dash-used-sources"><h4>БУДЕТ ИСПОЛЬЗОВАНО</h4><div>{[...draft.sources,'Аналитика','Документация'].map(name=><Badge tone="gray" key={name}><Database size={12}/>{name}</Badge>)}</div></section></div><aside className="panel dash-generation-log"><h3><Sparkles size={16}/>Что делает ИИ сейчас <span>● LIVE</span></h3>{['Собирает KPI карточки','Группирует рейсы по статусам','Формирует рейтинг перевозчиков','Подготавливает динамику по дням','Оценивает карту'].map((label,i)=><div className={percent>i*20?'is-running':''} key={label}><CheckCircle2 size={20}/><span><strong>{label}</strong><p>{['Подбирает метрики и рассчитывает значения','Формирует сегменты и считает распределение','Сортирует по ключевым показателям и трендам','Строит временной ряд и проверяет аномалии','Анализирует территориальное распределение'][i]}</p></span></div>)}</aside></div>}
 <footer className="dash-wizard-footer"><button className="btn" onClick={back}><ArrowLeft size={14}/>{draft.step===4?'Отменить генерацию':'Назад'}</button>{draft.step<4&&<button className="btn btn-primary" disabled={draft.step===2&&!draft.sources.length} onClick={next}>{draft.step===3?'Создать дашборд':'Продолжить'}<ArrowRight size={15}/></button>}{draft.step===4&&<span className="muted">Черновик откроется автоматически</span>}</footer>
 </>}
 </div>;
}

const CARRIERS=['ООО «МСК-НТ»','ООО «Хартия»','ООО «ЭкоТранс»','ООО «МКМ-Логистика»','ООО «Эколайн»'];
const ORIGINS=['ЖК «ЗИЛАРТ»','Строительная площадка № 12','Промзона «Калибр»','Квартал «Нагатино»','Объект «Сити»'];
const DESTINATIONS=['КПО «Нева»','КПО «Север»','КПО «Восток»','КПО «Юг»','КПО «Экоград»'];
type Trip={day:number;hour:number;carrier:number;origin:number;destination:number;mass:number;waste:number;completed:boolean};
const TRIPS:Trip[]=Array.from({length:30},(_,day)=>Array.from({length:35+(day*17%75)},(_,i)=>({day,hour:[6,7,8,9,10,10,11,11,11,12,12,13,13,14,14,14,15,15,16,17,18,19,20,21,22,23][(i*7+day*3)%26],carrier:[0,0,0,0,1,1,1,2,2,3,4][(i*7+day)%11],origin:(i+Math.floor(i/7)+day)%5,destination:(Math.floor(i/3)+day*2)%5,mass:Math.round((5+((i*37+day*13)%130)/10)*10)/10,waste:(i+day)%3,completed:(i+day*3)%17!==0}))).flat();
function dataset(settings:EditorSettings){const days=settings.period==='30 дней'?30:settings.period==='14 дней'?14:7;return TRIPS.filter(t=>t.day<days&&(settings.carrier==='Все перевозчики'||CARRIERS[t.carrier]===settings.carrier)&&(settings.origin==='Все объекты образования'||ORIGINS[t.origin]===settings.origin)&&(settings.waste==='Все виды отходов'||['ТКО','Строительные','Промышленные'][t.waste]===settings.waste));}
function chartOption(id:string,config:WidgetConfig,trips:Trip[],light:boolean):EChartsCoreOption{
 const text=light?'#778092':'#77869c';const line=light?'#edf0f5':'#1b2636';const days=Math.max(7,...trips.map(t=>t.day+1));const daily=Array.from({length:days},(_,d)=>Math.round(trips.filter(t=>t.day===d).reduce((sum,t)=>sum+t.mass,0)));
 const style={color:text,fontFamily:'Golos Text, sans-serif',fontSize:9};
 const base:EChartsCoreOption={animationDuration:400,backgroundColor:'transparent',color:[config.color],textStyle:style,tooltip:{trigger:'axis',backgroundColor:light?'#fff':'#142033',borderColor:line,textStyle:{color:light?'#152238':'#e9f0ff',fontSize:11},confine:true},grid:{left:12,right:16,top:20,bottom:config.legend?30:16,outerBoundsMode:'same',outerBoundsContain:'axisLabel'},legend:{show:config.legend,bottom:0,textStyle:style},xAxis:{type:'category',data:daily.map((_,i)=>String(i+1).padStart(2,'0')+'.11'),axisLine:{lineStyle:{color:line}},axisTick:{show:false},axisLabel:style},yAxis:{type:'value',splitLine:{show:config.grid,lineStyle:{color:line,type:'dashed'}},axisLabel:style}};
 if(config.type==='heatmap'){
 const hours=Array.from({length:18},(_,i)=>i+6);const cells=Array.from({length:7*18},(_,i)=>{const day=Math.floor(i/18),hour=hours[i%18];const value=trips.filter(t=>t.day%7===day&&t.hour===hour).length;return [i%18,day,value];});
 return {...base,grid:{left:35,right:12,top:config.legend?29:12,bottom:35},legend:{show:config.legend,top:0,textStyle:style},tooltip:{...base.tooltip as object,trigger:'item',formatter:(p:{value:number[]})=>['Пн','Вт','Ср','Чт','Пт','Сб','Вс'][p.value[1]]+', '+hours[p.value[0]]+':00 · '+p.value[2]+' рейсов'},xAxis:{type:'category',data:hours.map(h=>h+':00'),axisLabel:{...style,interval:2},axisLine:{show:false},splitArea:{show:false}},yAxis:{type:'category',data:['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],axisLabel:style,axisLine:{show:false},axisTick:{show:false}},visualMap:{min:0,max:Math.max(1,...cells.map(c=>c[2])),calculable:false,orient:'horizontal',left:'center',bottom:0,itemHeight:80,itemWidth:5,textStyle:{color:text,fontSize:8},inRange:{color:light?['#eaf3ff',config.color,'#8bd079']:['#11243b',config.color,'#8bd079','#e7bf58']}},series:[{name:'Интенсивность, рейсы',type:'heatmap',data:cells,label:{show:true,color:light?'#152238':'#e2ebfc',fontSize:7},itemStyle:{borderWidth:config.grid?2:0,borderColor:light?'#ffffff':'#080e17'}}]};
 }
 if(config.type==='scatter'){
 const points=Array.from({length:48},(_,i)=>{const subset=trips.filter((_,n)=>n%48===i);const count=subset.length;return [Math.round(count*(7+(i*13%16))),Math.round(subset.reduce((sum,t)=>sum+t.mass,0)*(1+(i%4)/10))];});
 return {...base,tooltip:{...base.tooltip as object,trigger:'item',formatter:(p:{value:number[]})=>'Рейсы: '+p.value[0]+'<br/>Масса: '+num(p.value[1])+' т'},grid:{left:36,right:18,top:20,bottom:25},xAxis:{type:'value',name:'Рейсы',nameLocation:'middle',nameGap:19,nameTextStyle:style,axisLabel:style,splitLine:{show:config.grid,lineStyle:{color:line,type:'dashed'}}},yAxis:{type:'value',name:'Масса, т',nameTextStyle:style,axisLabel:style,splitLine:{show:config.grid,lineStyle:{color:line,type:'dashed'}}},series:[{name:'Перевозчики',type:'scatter',data:points,symbolSize:config.size,itemStyle:{color:config.color,opacity:.85},emphasis:{itemStyle:{shadowBlur:10,shadowColor:config.color}}}]};
 }
 if(config.type==='bar'&&['carriers','origins','destinations'].includes(id)){
 const key=id==='carriers'?'carrier':id==='origins'?'origin':'destination';const names=id==='carriers'?CARRIERS:id==='origins'?ORIGINS:DESTINATIONS;const rows=names.map((name,i)=>({name,value:Math.round(trips.filter(t=>t[key]===i).reduce((s,t)=>s+t.mass,0))})).sort((a,b)=>a.value-b.value);
 return {...base,grid:{left:6,right:37,top:8,bottom:config.legend?24:4,outerBoundsMode:'same',outerBoundsContain:'axisLabel'},xAxis:{type:'value',show:config.grid,axisLabel:{show:false},axisLine:{show:false},axisTick:{show:false},splitLine:{show:config.grid,lineStyle:{color:line,type:'dashed'}}},yAxis:{type:'category',data:rows.map(r=>r.name),axisLabel:{...style,fontSize:9,width:125,overflow:'truncate'},axisTick:{show:false},axisLine:{show:false}},tooltip:{...base.tooltip as object,trigger:'axis',axisPointer:{type:'shadow'}},series:[{type:'bar',name:'Масса, т',data:rows.map(r=>r.value),barWidth:5,showBackground:true,backgroundStyle:{color:light?'#f0f3f7':'#111c2d'},itemStyle:{color:config.color,borderRadius:3},label:{show:true,position:'right',color:light?'#263247':'#d1e0f6',fontSize:9,formatter:(p:{value:number})=>num(p.value)}}]};
 }
 return {...base,series:[{name:'Масса, т',type:config.type==='line'?'line':'bar',data:daily,smooth:true,symbol:'none',barMaxWidth:20,itemStyle:{color:config.color,borderRadius:3},lineStyle:{color:config.color,width:2},areaStyle:config.type==='line'?{color:config.color,opacity:.1}:undefined}]};
}

function Sparkline({color,index}:{color:string;index:number}){const values=Array.from({length:24},(_,i)=>18+Math.sin((i+index)/3)*7+(i*7%9));const d=values.map((y,i)=>(i?'L':'M')+(i*5)+','+y).join(' ');return <svg className="dash-sparkline" viewBox="0 0 115 40" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id={'dash-grad-'+index} x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor={color} stopOpacity=".3"/><stop offset="1" stopColor={color} stopOpacity="0"/></linearGradient></defs><path d={d+' L115,40 L0,40 Z'} fill={'url(#dash-grad-'+index+')'}/><path d={d} stroke={color} strokeWidth="1.2" fill="none"/></svg>;}

function OperationalBoard({settings,onChange,editable=false,onSelect,boardRef}:{settings:EditorSettings;onChange:(p:Partial<EditorSettings>)=>void;editable?:boolean;onSelect?:(id:string)=>void;boardRef?:React.RefObject<HTMLDivElement|null>}){
 const trips=useMemo(()=>dataset(settings),[settings.period,settings.carrier,settings.origin,settings.waste]);const light=settings.theme==='light';
 const total=trips.reduce((s,t)=>s+t.mass,0);const completed=trips.filter(t=>t.completed).length;const dayCount=settings.period==='30 дней'?30:settings.period==='14 дней'?14:7;
 const kpis=[{title:'Средняя масса рейса',value:num(total/Math.max(1,trips.length),1),unit:'т',delta:'+8,7%',color:'#8692a4'},{title:'Рейсов на одно ТС',value:num(trips.length/42,1),unit:'рейсов',delta:'+1,7%',color:'#3c8dff'},{title:'Среднее в день',value:num(total/dayCount,0),unit:'т / день',delta:'+36,6%',color:'#9acb52'},{title:'Доля завершённых рейсов',value:num(completed/Math.max(1,trips.length)*100,1),unit:'%',delta:'+4,1%',color:'#a980ff'},{title:'Топ-5 объектов образования',value:num(total*.117,0),unit:'тонн',delta:'−4,1%',color:'#70c8e3'},{title:'Топ-5 перевозчиков',value:num(total*.133,0),unit:'тонн',delta:'+2,9%',color:'#ee9c4d'}];
 const select=(id:string)=>{if(editable)onSelect?.(id);};
 return <div className={'dash-board '+(light?'dash-board-light':'')} ref={boardRef}>
 <div className="dash-board-top"><div className="dash-board-tabs">{['Свод','Аналитика','Данные'].map((tab,i)=><button className={settings.tab===tab?'is-active':''} key={tab} onClick={()=>onChange({tab})}>{i===0?<Grid2X2 size={11}/>:i===1?<BarChart3 size={11}/>:<Database size={11}/>} {tab}</button>)}</div><div className="dash-board-filters"><select aria-label="Период дашборда" value={settings.period} onChange={e=>onChange({period:e.target.value})}>{['7 дней','14 дней','30 дней'].map(v=><option key={v}>{v}</option>)}</select><select aria-label="Перевозчик" value={settings.carrier} onChange={e=>onChange({carrier:e.target.value})}>{['Все перевозчики',...CARRIERS].map(v=><option key={v}>{v}</option>)}</select><select aria-label="Объект образования" value={settings.origin} onChange={e=>onChange({origin:e.target.value})}>{['Все объекты образования',...ORIGINS].map(v=><option key={v}>{v}</option>)}</select><select aria-label="Вид отходов" value={settings.waste} onChange={e=>onChange({waste:e.target.value})}>{['Все виды отходов','ТКО','Строительные','Промышленные'].map(v=><option key={v}>{v}</option>)}</select></div></div>
 <div className="dash-kpi-grid">{kpis.map((kpi,i)=><button className={'dash-kpi '+(settings.tab==='Свод'?'dash-kpi-large':'')} key={kpi.title} onClick={()=>select(i===3?'heatmap':i===4?'origins':i===5?'carriers':'efficiency')}><div>{kpi.title}</div><strong>{kpi.value}<small>{kpi.unit}</small><span className={kpi.delta.startsWith('−')?'is-negative':''}>{kpi.delta}<em>к пред. периоду</em></span></strong><Sparkline color={kpi.color} index={i}/><span className="dash-kpi-note">{['Нагрузка на один рейс','Использование транспорта','Хороший рост показателя','Снижение доли отмен','Ключевые объекты','Увеличение концентрации'][i]}</span></button>)}</div>
 {settings.tab==='Данные'?<div className="dash-board-data"><div className="dash-board-data-heading"><h3>Реестр рейсов</h3><span>{num(trips.length)} записей</span><button onClick={()=>downloadTrips(trips)}><ArrowDownToLine size={13}/> Скачать CSV</button></div><table><thead><tr><th>Рейс</th><th>Дата</th><th>Перевозчик</th><th>Объект образования</th><th>Масса, т</th><th>Статус</th></tr></thead><tbody>{trips.slice(0,11).map((trip,i)=><tr key={i}><td>Р-{String(1200+i)}</td><td>{String(trip.day+1).padStart(2,'0')}.11.2026</td><td>{CARRIERS[trip.carrier]}</td><td>{ORIGINS[trip.origin]}</td><td>{num(trip.mass,1)}</td><td><span className={trip.completed?'dash-trip-done':'dash-trip-late'}>{trip.completed?'Завершён':'В работе'}</span></td></tr>)}</tbody></table></div>:<div className="dash-widget-grid">{WIDGETS.map(widget=>{const config=settings.configs[widget.id];return <section role={editable?'button':undefined} tabIndex={editable?0:undefined} aria-label={editable?'Настроить виджет '+widget.title:undefined} className={'dash-widget dash-widget-'+widget.id+' '+(editable&&settings.selected===widget.id?'is-selected':'')} key={widget.id} onClick={()=>select(widget.id)} onKeyDown={e=>{if(e.target===e.currentTarget&&(e.key==='Enter'||e.key===' ')){e.preventDefault();select(widget.id);}}}><div className="dash-widget-title"><div><h3>{widget.title}</h3><span>{widget.sub}</span></div>{editable&&<button className="dash-widget-menu" aria-label={'Настроить '+widget.title} onClick={e=>{e.stopPropagation();select(widget.id);}}><MoreHorizontal size={14}/></button>}</div><Chart option={chartOption(widget.id,config,trips,light)} label={widget.title+' — интерактивный график'}/>{widget.id==='carriers'&&<div className="dash-widget-total">Итого <strong>{num(total)} т</strong><span>100%</span></div>}</section>;})}</div>}
 <div className="dash-board-foot"><span><span className="dash-live-dot"/>Демонстрационные данные · Москва</span><span>{num(trips.length)} рейсов · {settings.period.toLowerCase()}</span></div>
 </div>;
}
function downloadTrips(trips:Trip[]){const csv='\uFEFFДата;Час;Перевозчик;Объект образования;Объект приёма;Масса, т;Статус\n'+trips.map(t=>[String(t.day+1).padStart(2,'0')+'.11.2026',t.hour+':00',CARRIERS[t.carrier],ORIGINS[t.origin],DESTINATIONS[t.destination],String(t.mass).replace('.',','),t.completed?'Завершён':'В работе'].join(';')).join('\n');downloadText('Рейсы_демонстрационные.csv',csv,'text/csv;charset=utf-8');toast('CSV с текущей выборкой скачан');}

function DashboardEditor({id,published}:{id:string;published:boolean}){
 const navigate=useNavigate();const dashboards=useDemo(s=>s.dashboards);const saveDashboard=useDemo(s=>s.saveDashboard);const dashboard=dashboards.find(d=>d.id===id);const [settings,setSettings]=useState<EditorSettings>(()=>({...defaultSettings(dashboard?.theme==='light'?'light':'dark'),...readSaved().editors?.[id]}));
 const [controlTab,setControlTab]=useState('Визуализация');const [sideTab,setSideTab]=useState('Комментарии команды');const [comment,setComment]=useState('');const [shareOpen,setShareOpen]=useState(false);const [publishOpen,setPublishOpen]=useState(false);const [embedded,setEmbedded]=useState(false);const [ask,setAsk]=useState('');const [aiReply,setAiReply]=useState('');const [replyTo,setReplyTo]=useState('');const [menuOpen,setMenuOpen]=useState(false);const boardRef=useRef<HTMLDivElement>(null);const inputRef=useRef<HTMLInputElement>(null);
 useEffect(()=>{writeSaved({editors:{...readSaved().editors,[id]:settings}});},[id,settings]);
 if(!dashboard)return <div className="dash-page dash-empty"><LayoutDashboard size={42}/><h1>Дашборд не найден</h1><p>Он мог быть удалён при сбросе демонстрации.</p><Link className="btn btn-primary" to="/dashboards">К дашбордам</Link></div>;
 function update(p:Partial<EditorSettings>){setSettings(s=>({...s,...p}));}
 function config(p:Partial<WidgetConfig>){setSettings(s=>({...s,configs:{...s.configs,[s.selected]:{...s.configs[s.selected],...p}}}));}
 const selected=WIDGETS.find(w=>w.id===settings.selected)||WIDGETS[4];const selectedConfig=settings.configs[settings.selected];const url=new URL((import.meta.env.BASE_URL||'/')+'#/dashboards/'+id,window.location.origin).href;
 async function copy(value=url){try{await navigator.clipboard.writeText(value);toast('Ссылка скопирована');}catch{setShareOpen(true);toast('Выделите и скопируйте ссылку');}}
 function publish(){if(!dashboard)return;saveDashboard({...dashboard,published:true,theme:settings.theme,period:settings.period,updated:'Только что'});setPublishOpen(false);navigate('/dashboards/'+id);toast('Дашборд опубликован в локальной демонстрации');}
 function addComment(){if(!comment.trim())return;setSettings(s=>({...s,comments:[...s.comments,{id:uid(),name:'Анастасия К.',initials:'АК',text:(replyTo?'@'+replyTo+' ':'')+comment.trim(),time:new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}),likes:0}]}));setComment('');setReplyTo('');toast('Комментарий добавлен');}
 async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await boardRef.current?.requestFullscreen();}catch{toast('Полноэкранный режим недоступен в этом браузере');}}
 function askAssistant(value:string){setAsk(value);setAiReply(/компакт|меньше/i.test(value)?'Сделал точки компактнее. Размер — 4 px.':/легенд/i.test(value)?'Включил легенду выбранного графика.':/цвет|красн/i.test(value)?'Обновил цвет выбранного графика.':'В демонстрации могу изменить выбранный график: попробуйте «сделай компактнее», «покажи легенду» или «измени цвет».');if(/компакт|меньше/i.test(value))config({size:4});else if(/легенд/i.test(value))config({legend:true});else if(/цвет|красн/i.test(value))config({color:'#f43f5e'});}
 const board=<OperationalBoard settings={settings} onChange={update} editable={!published} onSelect={selected=>{update({selected});setControlTab('Визуализация');}} boardRef={boardRef}/>;
 return <div className={'dash-editor '+(published?'dash-published':'')}>
 {!published?<><main className="dash-editor-main"><header className="dash-editor-heading"><Link to="/dashboards" className="dash-back-link" title="Все дашборды"><ArrowLeft size={15}/></Link><strong>{dashboard.name}</strong><div><button className="dash-text-button" onClick={()=>setShareOpen(true)}><Share2 size={15}/>Поделиться</button><div className="dash-more-wrap"><button className="icon-btn" aria-label="Действия с дашбордом" onClick={()=>setMenuOpen(!menuOpen)}><MoreHorizontal size={18}/></button>{menuOpen&&<div className="dash-more-menu"><button onClick={()=>{downloadTrips(dataset(settings));setMenuOpen(false);}}><ArrowDownToLine size={14}/> Скачать CSV</button><button onClick={()=>{void fullscreen();setMenuOpen(false);}}><Maximize2 size={14}/>Во весь экран</button><button onClick={()=>{update({theme:settings.theme==='dark'?'light':'dark'});setMenuOpen(false);}}><Sun size={14}/>Сменить тему</button></div>}</div><button className="btn btn-primary" onClick={()=>setPublishOpen(true)}>Опубликовать <Sparkles size={14}/></button></div></header>
 {board}
 <section className="panel dash-widget-settings"><div className="dash-widget-settings-top"><p><strong>Выбран виджет:</strong> {selected.title}</p><nav>{['Основные','Данные','Визуализация','Оси и легенда','Фильтры'].map(tab=><button key={tab} className={controlTab===tab?'is-active':''} onClick={()=>setControlTab(tab)}>{tab}</button>)}</nav></div>
 {controlTab==='Визуализация'?<div className="dash-visual-controls"><div><label>Тип графика</label><div className="dash-chart-types">{[{type:'scatter' as ChartKind,name:'Точечный',icon:Grid2X2},{type:'line' as ChartKind,name:'Линейный',icon:LineChart},{type:'bar' as ChartKind,name:'Столбчатый',icon:BarChart3},{type:'heatmap' as ChartKind,name:'Тепловой',icon:Map}].map(({type,name,icon:Icon})=><button aria-pressed={selectedConfig.type===type} className={selectedConfig.type===type?'is-active':''} key={type} onClick={()=>config({type})}><Icon size={21}/><span>{name}</span></button>)}</div></div><div className="dash-color-control"><label>Цветовая схема</label><div className="dash-color-swatches">{['#477bff','#43be68','#a277ed','#ef3c59','#ff951c','#18bca2'].map(color=><button title={'Цвет '+color} aria-label={'Цвет '+color} aria-pressed={selectedConfig.color===color} className={selectedConfig.color===color?'is-active':''} style={{background:color}} key={color} onClick={()=>config({color})}/>)}<label className="dash-custom-color"><Plus size={12}/><input aria-label="Другой цвет графика" type="color" value={selectedConfig.color} onChange={e=>config({color:e.target.value})}/></label></div><label>Размер точек</label><div className="dash-range"><input aria-label="Размер точек" type="range" min="3" max="15" value={selectedConfig.size} onChange={e=>config({size:Number(e.target.value)})}/><output>{selectedConfig.size} px</output></div></div><div className="dash-toggles"><label>Показывать легенду<button className={'dash-switch '+(selectedConfig.legend?'is-on':'')} role="switch" aria-checked={selectedConfig.legend} aria-label="Показывать легенду" onClick={()=>config({legend:!selectedConfig.legend})}><span/></button></label><label>Показывать сетку<button className={'dash-switch '+(selectedConfig.grid?'is-on':'')} role="switch" aria-checked={selectedConfig.grid} aria-label="Показывать сетку" onClick={()=>config({grid:!selectedConfig.grid})}><span/></button></label></div></div>:controlTab==='Основные'?<div className="dash-settings-form"><label>Виджет<select value={settings.selected} onChange={e=>update({selected:e.target.value})}>{WIDGETS.map(w=><option value={w.id} key={w.id}>{w.title}</option>)}</select></label><label>Цветовая тема<Choice value={settings.theme==='dark'?'Тёмная':'Светлая'} onChange={theme=>update({theme:theme==='Тёмная'?'dark':'light'})} options={['Тёмная','Светлая']}/></label><button className="btn" onClick={()=>void fullscreen()}><Maximize2 size={16}/>Во весь экран</button></div>:controlTab==='Данные'?<div className="dash-settings-form"><div><strong>Реестры рейсов · демонстрационный набор</strong><p>{num(dataset(settings).length)} записей в текущей выборке. Источники: {dashboard.sources.join(', ')}.</p></div><button className="btn" onClick={()=>downloadTrips(dataset(settings))}><ArrowDownToLine size={16}/>Скачать CSV</button></div>:controlTab==='Оси и легенда'?<div className="dash-settings-form"><div><strong>Оси и подписи</strong><p>Горизонтальная ось — {selectedConfig.type==='scatter'?'число рейсов':'дата / категория'}. Вертикальная — масса отходов, т.</p></div><label className="dash-checkbox"><input type="checkbox" checked={selectedConfig.legend} onChange={e=>config({legend:e.target.checked})}/>Легенда</label><label className="dash-checkbox"><input type="checkbox" checked={selectedConfig.grid} onChange={e=>config({grid:e.target.checked})}/>Линии сетки</label></div>:<div className="dash-settings-form"><label>Период<select value={settings.period} onChange={e=>update({period:e.target.value})}>{['7 дней','14 дней','30 дней'].map(v=><option key={v}>{v}</option>)}</select></label><label>Перевозчик<select value={settings.carrier} onChange={e=>update({carrier:e.target.value})}>{['Все перевозчики',...CARRIERS].map(v=><option key={v}>{v}</option>)}</select></label><button className="btn" onClick={()=>update({period:'7 дней',carrier:'Все перевозчики',origin:'Все объекты образования',waste:'Все виды отходов'})}>Сбросить фильтры</button></div>}
 </section><div className="dash-editor-ai"><Prompt onSubmit={askAssistant}/>{aiReply&&<p className="dash-ai-result"><Sparkles size={15}/>{aiReply}<button aria-label="Скрыть ответ ассистента" onClick={()=>setAiReply('')}><X size={13}/></button></p>}</div>
 </main><aside className="dash-comments"><div className="dash-comments-tabs">{['Комментарии команды','Задача ИИ'].map(tab=><button key={tab} className={sideTab===tab?'is-active':''} onClick={()=>setSideTab(tab)}>{tab}</button>)}</div>{sideTab==='Комментарии команды'?<><div className="dash-comments-list">{settings.comments.map(c=><article className="dash-comment" key={c.id}><div className="dash-comment-heading"><span className="dash-avatar">{c.avatar?<img src={asset(c.avatar)} alt=""/>:c.initials}</span><div><strong>{c.name}</strong><span>{c.time}</span></div><button className="icon-btn" aria-label={'Ссылка на комментарий '+c.name} onClick={()=>void copy(url+'#comment-'+c.id)}><MoreHorizontal size={14}/></button></div><p>{c.text}</p><div className="dash-comment-actions"><button onClick={()=>{setReplyTo(c.name);inputRef.current?.focus();}}>Ответить</button><button onClick={()=>update({comments:settings.comments.map(item=>item.id===c.id?{...item,liked:!item.liked,likes:item.likes+(item.liked?-1:1)}:item)})} className={c.liked?'is-liked':''}>Нравится</button><button aria-label={'Нравится комментарий '+c.name} onClick={()=>update({comments:settings.comments.map(item=>item.id===c.id?{...item,liked:!item.liked,likes:item.likes+(item.liked?-1:1)}:item)})}><ThumbsUp size={12}/>{c.likes}</button></div></article>)}</div>{replyTo&&<div className="dash-replying">Ответ для {replyTo}<button aria-label="Отменить ответ" onClick={()=>setReplyTo('')}><X size={12}/></button></div>}<form className="dash-comment-input" onSubmit={e=>{e.preventDefault();addComment();}}><input ref={inputRef} aria-label="Комментарий команде" placeholder="Комментарий и @коллега" value={comment} onChange={e=>setComment(e.target.value)}/><button type="submit" aria-label="Отправить комментарий" disabled={!comment.trim()}><ArrowUp size={16}/></button></form></>:<div className="dash-ai-task"><IconBox><Sparkles size={24}/></IconBox><h3>Доработайте дашборд с ИИ</h3><p>Выберите виджет и опишите изменение. Ассистент применит его к текущей визуализации.</p>{['Сделай точки компактнее','Покажи легенду','Измени цвет на красный'].map(v=><button className="btn" key={v} onClick={()=>askAssistant(v)}>{v}<ArrowRight size={13}/></button>)}{ask&&<div className="dash-inline-note"><strong>{ask}</strong><p>{aiReply}</p></div>}</div>}</aside></>:<main className="dash-page dash-publication"><header className="dash-publication-heading"><div><h1>{dashboard.published?'Дашборд готов к публикации':'Предпросмотр дашборда'}</h1><div className="dash-publish-meta"><Badge tone={dashboard.published?'green':'gray'}><Check size={13}/>{dashboard.published?'Опубликовано':'Черновик'}</Badge><span>{dashboard.updated}</span></div><p>{dashboard.published?'Дашборд опубликован в локальной демонстрации и доступен по ссылке в этом браузере.':'Проверьте показатели перед публикацией.'}</p></div><button className="btn btn-secondary" onClick={()=>{if(dashboard.published){saveDashboard({...dashboard,published:false});toast('Локальная публикация снята');}navigate('/dashboards/'+id+'/edit');}}>{dashboard.published?'Снять с публикации':'Редактировать'}</button></header><div className="dash-publication-grid"><div className="dash-preview-board">{board}</div><aside><section className="panel dash-publication-params"><h3>Параметры публикации</h3>{[['Название',dashboard.name],['Описание','Оперативный дашборд по вывозу отходов и эффективности системы'],['Доступ',settings.access],['Обновление',settings.refresh]].map(([label,value])=><div key={label}><span>{label}</span><strong>{value}</strong></div>)}<div><span>Ссылка</span><button className="dash-text-button" onClick={()=>void copy()}>lab-cd / dashboards / {id}<Copy size={12}/></button></div></section><section className="panel dash-next-actions"><h3>Что можно сделать дальше</h3>{[{name:'Открыть дашборд',desc:'Развернуть интерактивный дашборд',icon:Play,action:()=>void fullscreen()},{name:'Поделиться ссылкой',desc:'Скопировать ссылку для демонстрации',icon:Share2,action:()=>setShareOpen(true)},{name:'Встроить в проект',desc:'Добавить дашборд к проекту',icon:Copy,action:()=>setEmbedded(true)},{name:'Настроить уведомления',desc:settings.notify?'Уведомления включены':'Следить за ключевыми метриками',icon:Bell,action:()=>{update({notify:!settings.notify});toast(settings.notify?'Демоуведомления отключены':'Демоуведомления включены');}},{name:'Экспорт данных',desc:'Скачать текущую выборку в CSV',icon:ArrowDownToLine,action:()=>downloadTrips(dataset(settings))}].map(({name,desc,icon:Icon,action})=><button key={name} onClick={action}><IconBox tone={['blue','green','violet','orange','green'][['Открыть дашборд','Поделиться ссылкой','Встроить в проект','Настроить уведомления','Экспорт данных'].indexOf(name)]}><Icon size={17}/></IconBox><span><strong>{name}</strong><small>{desc}</small></span><ChevronRight size={14}/></button>)}</section></aside></div><section className="dash-ai-search dash-publication-ai"><div><IconBox><Sparkles size={23}/></IconBox><div><h3>ИИ поможет улучшить уже опубликованный дашборд</h3><p>Опишите изменения — ИИ поможет его поправить</p></div></div><Prompt placeholder="Например: покажи легенду графика эффективности перевозчиков" onSubmit={v=>{askAssistant(v);toast('Изменение применено к демодашборду');}}/>{aiReply&&<p className="dash-inline-note">{aiReply}</p>}</section><div className="dash-publication-bottom"><Link className="btn" to="/dashboards"><ArrowLeft size={15}/>Все дашборды</Link><Link className="btn btn-primary" to={'/dashboards/'+id+'/edit'}><Pencil size={15}/>Редактировать дашборд</Link></div></main>}
 <Modal open={shareOpen} onClose={()=>setShareOpen(false)} title="Поделиться дашбордом"><p className="muted">Локальная демонстрационная ссылка. Получатель должен открыть прототип на том же адресе; черновики хранятся в этом браузере.</p><label className="dash-share-field">Ссылка<input readOnly value={url} onFocus={e=>e.target.select()}/></label><button className="btn btn-primary" onClick={()=>void copy()}><Copy size={15}/>Скопировать ссылку</button></Modal>
 <Modal open={publishOpen} onClose={()=>setPublishOpen(false)} title="Опубликовать дашборд"><p>Дашборд «{dashboard.name}» будет сохранён в локальной демонстрации.</p><label className="dash-share-field">Доступ<select value={settings.access} onChange={e=>update({access:e.target.value})}><option value="команда">Команда проекта</option><option value="только я">Только я</option></select></label><label className="dash-share-field">Обновление<select value={settings.refresh} onChange={e=>update({refresh:e.target.value})}><option value="ежедневно">Ежедневно</option><option value="вручную">Вручную</option></select></label><div className="dash-modal-actions"><button className="btn" onClick={()=>setPublishOpen(false)}>Отмена</button><button className="btn btn-primary" onClick={publish}><Check size={15}/>Опубликовать</button></div></Modal>
 <Modal open={embedded} onClose={()=>setEmbedded(false)} title="Встроить в проект"><p>Выберите проект, в который нужно добавить дашборд.</p><EmbedDashboard dashboard={dashboard} selected={settings.projectId} onDone={projectId=>{update({projectId});setEmbedded(false);}}/></Modal>
 </div>;
}
function EmbedDashboard({dashboard,onDone,selected}:{dashboard:Dashboard;onDone:(projectId:string)=>void;selected?:string}){const projects=useDemo(s=>s.projects);const [project,setProject]=useState(selected||projects[0]?.id||'');return <><label className="dash-share-field">Проект<select value={project} onChange={e=>setProject(e.target.value)}>{projects.map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></label><button className="btn btn-primary" disabled={!project} onClick={()=>{toast('Дашборд «'+dashboard.name+'» добавлен в демопроект');onDone(project);}}>Добавить в проект</button></>;}
